{
  "claims": [
    {
      "text": "The ephemeral nature of AWS G6 workers, including IP changes on stop/start and the idle reaper that can halt workers at any moment, makes them unsuitable for stateful model jobs where correctness depends on maintaining state between invocations.",
      "evidence_refs": ["ev-t3-ip-changes", "ev-t3-idle-reaper"]
    },
    {
      "text": "While the G6's EBS volume persists across stop/start, the process and GPU memory state are lost, which means that any job requiring continuity of execution context cannot rely on the worker's state.",
      "evidence_refs": ["ev-t3-ebs-persists"]
    },
    {
      "text": "The platform's design explicitly treats compute state as non-persistent, aligning with the principle that only long-term storage (S3/Tempo/Loki/Prometheus) should be relied upon for persistent data, while compute state is ephemeral.",
      "evidence_refs": ["ev-t3-registry-inmemory"]
    }
  ],
  "decision": "reject",
  "risks": [
    "Allowing stateful jobs on ephemeral workers risks job failure or incorrect behavior due to loss of state during worker lifecycle events.",
    "Stateful jobs may experience inconsistent results or require excessive reconciliation logic."
  ],
  "assumptions": [
    "Stateful model jobs are those where correctness is dependent on maintaining state between invocations.",
    "The system's architecture is designed to tolerate ephemeral compute nodes."
  ]
}
